// =============================================================================
// record-sale/index.ts
// Supabase Edge Function — Record a bike sale (employee + admin)
//
// Auth: admin OR employee (requireRole)
// Method: POST
//
// Body (JSON):
//   bike_id           string (uuid)
//   quantity          number (int >= 1)
//   customer_name     string
//   customer_phone    string (10 digits)
//   buyer_type        "Individual" | "Corporate"
//   payment_status    "Fully Paid" | "Partial" | "Pending"
//   amount_paid       number
//   request_id        string (uuid, generated by browser — idempotency key)
//   discount          { type: "percent"|"amount", value: number } | null
//   paperwork_charge  number (default 0)
//   modification_charge number (default 0)
//   modification_note string (optional)
//   extras            Array<{ part_id: string, qty: number }>
//
// Response:
//   { status: "committed", sale_log_id, sale_id, sheet_synced, warning? }
//   OR
//   { status: "pending_approval", pending_id }
// =============================================================================

import { createClient } from "npm:@supabase/supabase-js@2";
import { CORS_HEADERS, requireRole } from "../_shared/auth.ts";
import { computeSale } from "../_shared/pricing.ts";
import { getGoogleAccessToken, ensureHeaders, batchGetSheetValues } from "../_shared/google.ts";
import { updatePartStockCells } from "../_shared/parts_sheet.ts";
import { ServerTimer } from "../_shared/timing.ts";

function jsonResponse(body: unknown, status = 200, extraHeaders?: Record<string, string>): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...CORS_HEADERS, "Content-Type": "application/json", ...extraHeaders },
  });
}

// New A2 columns added to the Sold sheet (appended at end if missing)
const A2_SOLD_HEADERS = [
  "Original Price",
  "Discount Type",
  "Discount Value",
  "Discount Amount",
  "Paperwork Charge",
  "Modification Charge",
  "Modification Note",
  "Extra Products",
  "Extra Products Total",
  "Final Price",
  "Approval Status",
  "Approved By",
];

Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { status: 204, headers: CORS_HEADERS });
  }
  if (req.method !== "POST") {
    return jsonResponse({ error: "Method not allowed. Use POST." }, 405);
  }

  const timer = new ServerTimer();

  // ── Auth ───────────────────────────────────────────────────────────────────
  const auth = await timer.measure("auth", () => requireRole(req, ["admin", "employee"]));
  if (auth instanceof Response) return auth;
  const { userId, email: callerEmail, role } = auth;

  // ── Parse body ─────────────────────────────────────────────────────────────
  let body: Record<string, unknown>;
  try {
    body = await req.json();
  } catch {
    return jsonResponse({ error: "Invalid JSON in request body." }, 400);
  }

  // ── Validate required fields ───────────────────────────────────────────────
  const bike_id = String(body.bike_id ?? "").trim();
  const quantity = parseInt(String(body.quantity ?? "0"), 10);
  const customer_name = String(body.customer_name ?? "").trim();
  const customer_phone = String(body.customer_phone ?? "").trim();
  const buyer_type = String(body.buyer_type ?? "").trim();
  const payment_status = String(body.payment_status ?? "").trim();
  const amount_paid = Number(body.amount_paid ?? 0);
  const request_id = String(body.request_id ?? "").trim();
  const modification_note = String(body.modification_note ?? "").trim().slice(0, 500);

  if (!bike_id) return jsonResponse({ error: "bike_id is required." }, 400);
  if (!Number.isInteger(quantity) || quantity < 1)
    return jsonResponse({ error: "quantity must be a positive integer." }, 400);
  if (!customer_name || customer_name.length < 1 || customer_name.length > 200)
    return jsonResponse({ error: "customer_name is required (max 200 chars)." }, 400);
  if (!/^\d{10}$/.test(customer_phone))
    return jsonResponse({ error: "customer_phone must be exactly 10 digits." }, 400);
  if (!["Individual", "Corporate"].includes(buyer_type))
    return jsonResponse({ error: "buyer_type must be Individual or Corporate." }, 400);
  if (!["Fully Paid", "Partial", "Pending"].includes(payment_status))
    return jsonResponse({ error: "payment_status must be Fully Paid, Partial, or Pending." }, 400);
  if (!Number.isFinite(amount_paid) || amount_paid < 0)
    return jsonResponse({ error: "amount_paid must be a non-negative number." }, 400);
  if (!/^[0-9a-f-]{36}$/i.test(request_id))
    return jsonResponse({ error: "request_id must be a valid UUID." }, 400);

  const paperwork_charge = Math.max(0, Number(body.paperwork_charge ?? 0));
  const modification_charge = Math.max(0, Number(body.modification_charge ?? 0));
  if (!Number.isFinite(paperwork_charge))
    return jsonResponse({ error: "paperwork_charge must be a non-negative number." }, 400);
  if (!Number.isFinite(modification_charge))
    return jsonResponse({ error: "modification_charge must be a non-negative number." }, 400);

  // Discount
  let discountInput: { type: "percent" | "amount"; value: number } | null = null;
  if (body.discount !== null && body.discount !== undefined) {
    const d = body.discount as Record<string, unknown>;
    const dtype = String(d.type ?? "");
    const dval = Number(d.value ?? 0);
    if (!["percent", "amount"].includes(dtype))
      return jsonResponse({ error: "discount.type must be 'percent' or 'amount'." }, 400);
    if (!Number.isFinite(dval) || dval < 0)
      return jsonResponse({ error: "discount.value must be a non-negative number." }, 400);
    discountInput = { type: dtype as "percent" | "amount", value: dval };
  }

  // Extras
  const extrasRaw = Array.isArray(body.extras) ? body.extras as Record<string, unknown>[] : [];
  for (const ex of extrasRaw) {
    if (!ex.part_id || typeof ex.part_id !== "string")
      return jsonResponse({ error: "Each extra must have a part_id." }, 400);
    const exQty = parseInt(String(ex.qty ?? "0"), 10);
    if (!Number.isInteger(exQty) || exQty < 1)
      return jsonResponse({ error: "Each extra qty must be a positive integer." }, 400);
  }

  // ── Service-role Supabase client ───────────────────────────────────────────
  const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
  const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
  const sb = createClient(supabaseUrl, serviceRoleKey, {
    auth: { autoRefreshToken: false, persistSession: false },
  });

  // ── Load bike + parts in parallel ─────────────────────────────────────────
  interface PartRow {
    id: string;
    name: string;
    price: number;
    stock_qty: number;
    active: boolean;
  }
  const partIds = extrasRaw.map((ex) => ex.part_id as string);

  const [bikeResult, partsResult] = await timer.measure("db", () => Promise.all([
    sb.from("bikes")
      .select("id, name, price, quantity, availability, low_stock_threshold")
      .eq("id", bike_id)
      .single(),
    partIds.length > 0
      ? sb.from("parts").select("id, name, price, stock_qty, active").in("id", partIds)
      : Promise.resolve({ data: [], error: null }),
  ]));

  const { data: bike, error: bikeErr } = bikeResult;
  if (bikeErr || !bike) {
    return jsonResponse({ error: "Bike not found." }, 404);
  }
  if (bike.price === null || bike.price === undefined) {
    return jsonResponse({ error: "Price not set, ask admin." }, 422);
  }
  if (quantity > bike.quantity) {
    return jsonResponse({
      error: `Not enough stock — only ${bike.quantity} unit(s) available.`,
    }, 422);
  }

  let partsMap = new Map<string, PartRow>();
  if (partIds.length > 0) {
    const { data: partsData, error: partsErr } = partsResult;
    if (partsErr) {
      return jsonResponse({ error: "Failed to load parts." }, 500);
    }
    for (const p of (partsData ?? []) as PartRow[]) {
      partsMap.set(p.id, p);
    }
    // Validate each extra
    for (const ex of extrasRaw) {
      const part = partsMap.get(ex.part_id as string);
      const exQty = parseInt(String(ex.qty), 10);
      if (!part) {
        return jsonResponse({ error: `Part ${ex.part_id} not found.` }, 422);
      }
      if (!part.active) {
        return jsonResponse({ error: `Part "${part.name}" is not active.` }, 422);
      }
      if (exQty > part.stock_qty) {
        return jsonResponse({
          error: `Part "${part.name}" has only ${part.stock_qty} in stock (requested ${exQty}).`,
        }, 422);
      }
    }
  }

  // ── Build extras array with server prices ─────────────────────────────────
  const extrasForCompute = extrasRaw.map((ex) => {
    const part = partsMap.get(ex.part_id as string)!;
    return { unitPrice: Number(part.price), qty: parseInt(String(ex.qty), 10) };
  });

  const extrasForCommit = extrasRaw.map((ex) => {
    const part = partsMap.get(ex.part_id as string)!;
    return {
      part_id: ex.part_id as string,
      part_name: part.name,
      qty: parseInt(String(ex.qty), 10),
      unit_price: Number(part.price),
    };
  });

  // ── Compute sale (server-side; browser value ignored) ─────────────────────
  let computed;
  try {
    computed = computeSale({
      bikePrice: Number(bike.price),
      quantity,
      discount: discountInput,
      paperwork: paperwork_charge,
      modification: modification_charge,
      extras: extrasForCompute,
    });
  } catch (err) {
    return jsonResponse({ error: (err as Error).message }, 422);
  }

  // ── Approval path ──────────────────────────────────────────────────────────
  if (computed.needs_approval && role === "employee") {
    // Insert into pending_sales — no stock change, no Sheet row
    const { data: pending, error: pendErr } = await sb
      .from("pending_sales")
      .insert({
        request_id,
        requested_by: userId,
        requested_by_email: callerEmail,
        bike_id: bike_id,
        bike_name: bike.name,
        payload: {
          bike_id,
          quantity,
          customer_name,
          customer_phone,
          buyer_type,
          payment_status,
          amount_paid,
          request_id,
          discount: discountInput,
          paperwork_charge,
          modification_charge,
          modification_note,
          extras: extrasRaw,
        },
        original_price: computed.base,
        discount_amount: computed.discount_amount,
        discount_percent: computed.discount_percent_effective,
        final_price: computed.final_price,
        status: "pending",
      })
      .select("id")
      .single();

    if (pendErr) {
      // Unique violation on request_id = already submitted
      if (pendErr.code === "23505") {
        const { data: existing } = await sb
          .from("pending_sales")
          .select("id")
          .eq("request_id", request_id)
          .single();
        return jsonResponse({
          status: "pending_approval",
          pending_id: existing?.id,
        });
      }
      return jsonResponse({ error: "Failed to create approval request.", detail: pendErr.message }, 500);
    }

    return jsonResponse({ status: "pending_approval", pending_id: pending.id });
  }

  // ── Commit path (no approval needed, or admin) ────────────────────────────
  const approvedBy = computed.needs_approval && role === "admin" ? userId : null;
  const approvedAt = approvedBy ? new Date().toISOString() : null;

  let saleLogId: number;
  try {
    const { data: commitData, error: commitErr } = await timer.measure("db_commit", () =>
      sb.rpc("commit_sale", {
        p_bike_id: bike_id,
        p_quantity: quantity,
        p_logged_by: callerEmail ?? "unknown",
        p_employee_id: userId,
        p_customer_name: customer_name,
        p_customer_phone: customer_phone,
        p_buyer_type: buyer_type,
        p_payment_status: payment_status,
        p_amount_paid: amount_paid,
        p_request_id: request_id,
        p_original_price: computed.base,
        p_discount_type: discountInput?.type ?? null,
        p_discount_value: discountInput?.value ?? null,
        p_discount_amount: computed.discount_amount,
        p_paperwork_charge: paperwork_charge,
        p_modification_charge: modification_charge,
        p_modification_note: modification_note || null,
        p_extras_total: computed.extras_total,
        p_final_price: computed.final_price,
        p_approved_by: approvedBy,
        p_approved_at: approvedAt,
        p_extras: extrasForCommit,
      })
    );

    if (commitErr) {
      return jsonResponse({ error: commitErr.message }, 422);
    }
    saleLogId = commitData as number;
  } catch (err) {
    return jsonResponse({ error: (err as Error).message }, 500);
  }

  // ── Write to Google Sheet ─────────────────────────────────────────────────
  const clientEmail = Deno.env.get("GOOGLE_CLIENT_EMAIL");
  const privateKeyPem = Deno.env.get("GOOGLE_PRIVATE_KEY")?.replace(/\\n/g, "\n");
  const sheetId = Deno.env.get("GOOGLE_SHEET_ID");

  let sheetSynced = false;
  let sheetWarning: string | undefined;
  let saleId = "";

  if (clientEmail && privateKeyPem && sheetId) {
    try {
      // Get token + fetch new stock level in parallel
      const [accessToken, freshBikeRes] = await timer.measure("google_token_and_stock", () =>
        Promise.all([
          getGoogleAccessToken(clientEmail, privateKeyPem!),
          sb.from("bikes").select("quantity").eq("id", bike_id).single(),
        ])
      );
      const newStockLevel = freshBikeRes.data?.quantity ?? 0;

      // Generate Sale ID
      saleId = `SALE-${Date.now().toString(36).toUpperCase()}`;

      // Batch-read Sold!1:1, Documents!1:1, Stock!A:A in one API call
      const batchRanges = ["Sold!1:1", "Documents!1:1", "Stock!A:A"];
      const batchData = await timer.measure("sheets_read", () =>
        batchGetSheetValues(accessToken, sheetId!, batchRanges)
      );

      let soldHeaders: string[] = (batchData.get("Sold!1:1")?.[0] ?? []).map((h) => String(h).trim());
      const docHeaders: string[] = (batchData.get("Documents!1:1")?.[0] ?? []).map((h) => String(h).trim());
      const stockColA: string[][] = (batchData.get("Stock!A:A") ?? []) as string[][];

      // Ensure A2 headers in Sold (may append if missing — not in batch to avoid complexity)
      const missingHeaders = A2_SOLD_HEADERS.filter(
        (h) => !soldHeaders.some((e) => e.toLowerCase() === h.toLowerCase())
      );
      if (missingHeaders.length > 0) {
        soldHeaders = await timer.measure("sheets_ensure_headers", () =>
          ensureHeaders(accessToken, sheetId!, "Sold", A2_SOLD_HEADERS)
        );
      }

      const formattedDate = new Date().toLocaleString("en-IN", {
        day: "2-digit", month: "short", year: "numeric",
        hour: "2-digit", minute: "2-digit", hour12: true,
        timeZone: "Asia/Kathmandu",
      });

      const finalAmountPaid = payment_status === "Fully Paid"
        ? computed.final_price
        : amount_paid;
      const balanceDue = Math.max(0, computed.final_price - finalAmountPaid);

      const extraProductsText = extrasForCommit
        .map((ex) => `${ex.part_name} x${ex.qty}`)
        .join("; ");

      const approvalStatus = (computed.needs_approval && role === "admin")
        ? "Approved"
        : "Not needed";

      let approverEmail = "";
      if (computed.needs_approval && role === "admin") {
        approverEmail = callerEmail ?? "";
      }

      const valueMap: Record<string, string | number> = {
        "date": formattedDate,
        "sale id": saleId,
        "bike name": bike.name,
        "quantity": quantity,
        "logged by": callerEmail ?? "unknown",
        "customer name": customer_name,
        "customer phone": customer_phone,
        "sold price": computed.sold_price,
        "buyer type": buyer_type,
        "payment status": payment_status,
        "amount paid": finalAmountPaid,
        "balance due": balanceDue,
        "new stock level": newStockLevel,
        "original price": computed.base,
        "discount type": discountInput?.type ?? "",
        "discount value": discountInput?.value ?? "",
        "discount amount": computed.discount_amount,
        "paperwork charge": paperwork_charge,
        "modification charge": modification_charge,
        "modification note": modification_note,
        "extra products": extraProductsText,
        "extra products total": computed.extras_total,
        "final price": computed.final_price,
        "approval status": approvalStatus,
        "approved by": approverEmail,
      };

      const rowValues = soldHeaders.map((h) => {
        const key = h.trim().toLowerCase();
        if (valueMap[key] !== undefined) return valueMap[key];
        if (key.includes("sale") && key.includes("id")) return saleId;
        if (key.includes("bike") && key.includes("name")) return bike.name;
        if (key.includes("customer") && key.includes("name")) return customer_name;
        if (key.includes("customer") && key.includes("phone")) return customer_phone;
        if (key.includes("logged")) return callerEmail ?? "unknown";
        if (key.includes("sold") && key.includes("price")) return computed.sold_price;
        if (key.includes("buyer")) return buyer_type;
        if (key.includes("payment") && key.includes("status")) return payment_status;
        if (key.includes("amount") && key.includes("paid")) return finalAmountPaid;
        if (key.includes("balance")) return balanceDue;
        if (key.includes("new") && key.includes("stock")) return newStockLevel;
        if (key.includes("date")) return formattedDate;
        if (key.includes("final") && key.includes("price")) return computed.final_price;
        return "";
      });

      // Build Documents row from cached headers
      const docRowValues = buildDocumentsRow(
        docHeaders, saleId, buyer_type, customer_name, customer_phone, bike.name, formattedDate
      );

      // Find Stock tab row for this bike
      let bikeRowIndex = -1;
      for (let i = 0; i < stockColA.length; i++) {
        if (stockColA[i]?.[0]?.trim().toLowerCase() === bike.name.trim().toLowerCase()) {
          bikeRowIndex = i + 1;
          break;
        }
      }

      // Run Sold append + Documents append + Stock update + Parts update all in parallel
      const appendUrl = `https://sheets.googleapis.com/v4/spreadsheets/${sheetId}/values/${encodeURIComponent("Sold")}!A1:append?valueInputOption=USER_ENTERED&insertDataOption=INSERT_ROWS`;
      const docAppendUrl = `https://sheets.googleapis.com/v4/spreadsheets/${sheetId}/values/${encodeURIComponent("Documents")}!A1:append?valueInputOption=USER_ENTERED&insertDataOption=INSERT_ROWS`;

      const writes: Promise<unknown>[] = [
        fetch(appendUrl, {
          method: "POST",
          headers: { Authorization: `Bearer ${accessToken}`, "Content-Type": "application/json" },
          body: JSON.stringify({ values: [rowValues] }),
        }).then(async (r) => {
          if (!r.ok) sheetWarning = `Sheet Sold row not written: ${await r.text()}`;
          else sheetSynced = true;
        }),
        docRowValues.length > 0
          ? fetch(docAppendUrl, {
            method: "POST",
            headers: { Authorization: `Bearer ${accessToken}`, "Content-Type": "application/json" },
            body: JSON.stringify({ values: [docRowValues] }),
          }).then((r) => r.ok ? null : r.text().then((t) => console.warn("[record-sale] Doc append warning:", t)))
          : Promise.resolve(),
      ];

      if (bikeRowIndex !== -1) {
        const stockUpdateRange = `Stock!C${bikeRowIndex}:D${bikeRowIndex}`;
        const stockUpdateUrl = `https://sheets.googleapis.com/v4/spreadsheets/${sheetId}/values/${encodeURIComponent(stockUpdateRange)}?valueInputOption=USER_ENTERED`;
        writes.push(
          fetch(stockUpdateUrl, {
            method: "PUT",
            headers: { Authorization: `Bearer ${accessToken}`, "Content-Type": "application/json" },
            body: JSON.stringify({ range: stockUpdateRange, majorDimension: "ROWS", values: [[newStockLevel, formattedDate]] }),
          }).then((r) => r.ok ? null : r.text().then((t) => console.warn("[record-sale] Stock update warning:", t)))
        );
      }

      if (extrasForCommit.length > 0) {
        const extraPartIds = extrasForCommit.map((ex) => ex.part_id);
        writes.push(
          updatePartStockCells(extraPartIds).then((res) => {
            if (!res.ok) console.warn("[record-sale] Parts tab stock sync warning:", res.error);
          }).catch((e) => console.warn("[record-sale] Parts tab stock sync error:", e))
        );
      }

      await timer.measure("sheets_write", () => Promise.all(writes));

    } catch (sheetErr) {
      sheetWarning = `Sheet sync failed: ${(sheetErr as Error).message}`;
    }
  } else {
    sheetWarning = "Google Sheets environment variables not configured.";
  }

  // Mark sheet_synced on the stock_log row
  await sb
    .from("stock_logs")
    .update({ sheet_synced: sheetSynced })
    .eq("id", saleLogId);

  timer.log("record-sale");
  const timingHeader = timer.getHeader();

  const response: Record<string, unknown> = {
    status: "committed",
    sale_log_id: saleLogId,
    sale_id: saleId,
    sheet_synced: sheetSynced,
    computed,
  };
  if (sheetWarning) response.warning = sheetWarning;

  return jsonResponse(response, 200, { "Server-Timing": timingHeader });
});

// ── Build Documents row from cached headers (pure, no network calls) ──────────
function buildDocumentsRow(
  headers: string[],
  saleId: string,
  buyerType: string,
  customerName: string,
  customerPhone: string,
  bikeName: string,
  formattedDate: string,
): (string | boolean)[] {
  if (headers.length === 0) {
    // Fallback: use hardcoded column order
    const isIndividual = buyerType.toLowerCase() === "individual";
    return [
      saleId, buyerType,
      isIndividual ? false : "Not Required",
      isIndividual ? false : "Not Required",
      isIndividual ? false : "Not Required",
      isIndividual ? false : "Not Required",
      isIndividual ? "Not Required" : false,
      isIndividual ? "Not Required" : false,
      isIndividual ? "Not Required" : false,
      isIndividual ? "Not Required" : false,
      false, false, false,
    ];
  }
  const isIndividual = buyerType.toLowerCase() === "individual";
  function isIndividualDocCol(h: string) {
    return h.includes("citizenship") || h.includes("nid") ||
      h.includes("passport") ||
      h.includes("driving") || h.includes("license") ||
      (h.includes("pan") && !h.includes("vat") && !h.includes("company"));
  }
  function isCorporateDocCol(h: string) {
    return h.includes("registration") || h.includes("company") ||
      (h.includes("pan") && h.includes("vat")) ||
      h.includes("board") || h.includes("authorization") || h.includes("signatory");
  }
  return headers.map((header) => {
    const h = header.trim().toLowerCase();
    if (h.includes("sale") && h.includes("id")) return saleId;
    if (h.includes("buyer") && h.includes("type")) return buyerType;
    if (h.includes("customer") && h.includes("name")) return customerName;
    if (h.includes("customer") && h.includes("phone")) return customerPhone;
    if (h.includes("bike")) return bikeName;
    if (h.includes("date")) return formattedDate;
    if (h.includes("handover")) return false;
    if (h.includes("payment") && h.includes("receipt")) return false;
    if (h.includes("insurance")) return false;
    const indCol = isIndividualDocCol(h);
    const corpCol = isCorporateDocCol(h);
    if (indCol && !corpCol) return isIndividual ? false : "Not Required";
    if (corpCol && !indCol) return isIndividual ? "Not Required" : false;
    return false;
  });
}



